import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // For navigation
import './login-page.css'; // Custom CSS for styling
import Header from '../../components/Header/Header'; // Header component
import Footer from '../../components/Footer/Footer'; // Footer component

const LoginPage: React.FC = () => {
  const [email, setEmail] = useState<string>('');
  const [password, setPassword] = useState<string>('');
  const [userType, setUserType] = useState<string>('');
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const navigate = useNavigate();

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isSubmitting) return;

    if (!email.trim() || !password.trim() || !userType.trim()) {
      alert('Please fill in all fields.');
      return;
    }

    setIsSubmitting(true);
    try {
      const response = await fetch("http://localhost:5000/login_user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password, userType }),
      });

      const data = await response.json();
      if (response.ok) {
        alert('Login successful!');
        localStorage.setItem("userEmail", data.user);
        localStorage.setItem("rollno", data.rollno);  // Store roll number

        if (userType === 'admin') {
          navigate('/admin');
        } else {
          navigate('/dashboard');
        }
      } else {
        alert(`Error: ${data.error}`);
      }
    } catch (error) {
      console.error("Login error:", error);
      alert("Something went wrong. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="login-page">
      <Header />
      <div className="login-container">
        <h2>Login</h2>
        <form onSubmit={handleLogin}>
          <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
          <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required />
          <div>
            <input type="radio" value="admin" checked={userType === "admin"} onChange={(e) => setUserType(e.target.value)} />
            Admin
            <input type="radio" value="student" checked={userType === "student"} onChange={(e) => setUserType(e.target.value)} />
            Student
          </div>
          <button type="submit" disabled={isSubmitting}>
            {isSubmitting ? "Logging in..." : "Login"}
          </button>
        </form>
      </div>
      <Footer />
    </div>
  );
};

export default LoginPage;
